ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_24"] = {
{"s5_camp_menu_twelve_019","any",1,"reg=military|tmp=seasoned|mood=funny",{1,"Omelet with ham - again",1,"Some plant up north made eight million of these, and I've drawn every single one",1,"Somebody up there knows exactly what they did"}},
{"s5_camp_range_photo_020","any",2,"reg=military|day=5,90|hour=16,5|mood=sad",{1,"Squad picture from the range back in May - everybody's squinting",2,"Tell me you're not doing this tonight",1,"Five of us in it, I'm just counting",2,"Put it in your ruck"}},
{"s5_camp_count_sandbags_021","any",3,"reg=military|hour=19,23|mood=calm",{1,"Four on, four off, you sleep when it's your four, you don't lie there thinking",2,"How do you not think?",1,"Count the sandbags, the mags, keep counting 'til your head's empty",3,"Sergeant counts out loud, it's the worst sound in Kentucky"}},
{"s5_camp_no_cadence_022","any",2,"reg=military|day=3,90|hour=5,8|mood=sad",{1,"Used to be you'd hear three companies calling cadence at once every morning on post",2,"Nobody runs anymore",1,"I miss hating it"}},
{"s5_camp_lusk_barber_023","any",3,"reg=military|day=10,90|mood=funny",{1,"Lusk is cutting hair behind the latrine, twenty cigarettes a head",2,"Lusk can't cut hair",3,"Nobody said he could, he's just the only one with scissors",1,"Look at Ortiz",2,"Oh no, oh, Ortiz"}},
{"s5_camp_ohio_am_station_024","any",2,"reg=military|role=soldier_green,soldier_nco,soldier|day=3,29|hour=20,23|mood=sad",{1,"Could we try the big Cincinnati AM station tonight? It comes in after dark - my mom always has it on",2,"Batteries are for the net, Ohio",1,"Five minutes, just to hear if they're still talking up there",2,"Five minutes, and you don't tell a soul I said yes"}},
{"s5_camp_corn_prices_025","any",3,"reg=military|day=4,29|mood=warm",{1,"Ohio got the Cincinnati station for a minute last night",2,"Anything on it?",1,"Farm report - corn futures, like nothing in the world was wrong",3,"He cry?",1,"He laughed, laughed till he had to sit down in the dirt - corn futures"}},
{"s5_camp_water_buffalo_026","any",2,"reg=military|hour=8,16|mood=calm",{1,"Water buffalo's down to a quarter, tastes like the tank",2,"Tastes like garden hose and hot plastic",1,"Drink it anyway - Rodgers didn't"}},
{"s5_camp_kane_cardboard_027","any",3,"reg=military|tmp=seasoned,fresh|day=8,90|mood=angry",{1,"Specialist Kane is not in charge of this squad",2,"Kane's the senior man since Sergeant Boyd",3,"I'm not asking to be in charge, I'm asking you to take your turn on the wire",1,"See? Already giving orders",3,"That's a schedule, it's on a piece of cardboard, look"}},
{"s5_camp_bug_juice_028","any",2,"reg=military|hour=19,23|mood=funny",{1,"This bug juice isn't doing a thing",2,"Army bug juice doesn't repel - it marinates",1,"I believe that, I can hear them saying grace"}},
{"s5_camp_motor_pool_raccoon_029","any",3,"reg=military|hour=22,4|mood=fear",{1,"Something's moving around in the motor pool",2,"Raccoon",1,"A raccoon don't drag its feet",3,"Both of you hush and listen",2,"Oh... oh no, that's no raccoon"}},
{"s5_camp_gulf_sky_030","any",2,"reg=military|mood=calm",{1,"You were in the Gulf, right, Sergeant? Was it like this?",2,"Hotter - bigger sky, enemy stayed down when you put him down",1,"That's it?",2,"And we knew when we were flying home, that's the big one"}},
{"s5_camp_foot_inspection_031","any",3,"reg=military|day=3,60|mood=calm",{1,"Boots off - everybody - foot check",2,"Right now, Sergeant?",1,"Right now, I lose one man to jungle rot in a Kentucky summer, I'll lose what's left of my mind",3,"Have you lost a man to jungle rot?",1,"Not yet, that's why your boots are off"}},
{"s5_camp_spades_032","any",4,"reg=military|hour=13,17|mood=funny",{1,"Spades - partners - Losers pull the next wire shift",2,"You cheat",3,"Everybody cheats at spades, come on",4,"I don't know how to play",1,"Perfect, you're with me"}},
{"s5_camp_eighty_four_033","any",2,"reg=military|tmp=seasoned,veteran|day=10,90|mood=grim",{1,"Eighty-four MREs - twenty-six mouths",2,"Three days and change",1,"Two and a half if Lusk keeps eating crackers in the dark",2,"I'll talk to Lusk"}},
{"s5_camp_whole_plan_034","any",2,"reg=military|role=soldier_green,soldier_nco|day=1,29|hour=16,5|mood=fear",{1,"Sergeant, what happens if they come over the wire tonight?",2,"Then you shoot the ones coming over, and you stay right next to me",1,"That's it? That's the plan?",2,"It's a good plan, it's got you and me in it"}},
{"s5_camp_chemlight_candle_035","any",3,"reg=military|day=5,60|hour=19,23|mood=warm",{1,"Today's Ohio's birthday",2,"How old?",1,"Nineteen",3,"I got a candle - well, it's a green chemlight",2,"Crack it inside your blouse and sing quiet - real quiet"}},
{"s5_camp_dear_mom_036","any",1,"reg=military|role=soldier_green|day=2,29|hour=21,5|mood=sad|world=hot",{1,"Dear Mom - I'm okay - it's hot, the food's not as bad as Dad said",1,"They say the phones will be back soon, so don't worry if I don't call",1,"Nobody said that, I just don't want her sitting by the phone"}},
{"s5_camp_no_birds_037","any",2,"reg=military|tmp=seasoned,veteran|day=2,30|mood=grim",{1,"Sent up a medevac request for Sims at 1400, answer was no birds fly into the quarantine",2,"So what do we do with him?",1,"What Doc says - Doc says keep him cool and keep somebody sitting with him",2,"And if he turns?",1,"Then somebody's already sitting with him"}},
{"s5_camp_positive_attitude_038","any",3,"reg=military|day=3,40|mood=funny",{1,"Word from battalion: maintain a positive attitude",2,"They sent that over the net? Those words?",1,"Maintain positive attitude - conserve ammunition, in that order",3,"Nice to know which one keeps them up at night"}},
{"s5_camp_is_this_the_army_039","any",2,"reg=military|hour=0,5|mood=fear",{1,"Somebody came up on our freq around three - no callsign, just a man asking, hello, is this the Army",2,"You answer?",1,"Not supposed to, keeps the net clear",2,"Did you answer him?",1,"Said yes sir, this is the Army, he didn't say anything else after that"}},
{"s5_camp_cinnamon_chili_040","any",3,"reg=military|day=2,29|mood=funny",{1,"Ohio says Cincinnati chili beats anything you can eat in Kentucky",2,"Chili on spaghetti - with cinnamon, that's a cry for help",3,"It's good! There's cheese on top!",2,"Private, we may all die in Kentucky, but not one of us is dying believing that"}},
{"s5_camp_campaign_hat_041","any",2,"reg=military|day=1,40|mood=calm",{1,"Drill sergeant from the training brigade is on our stretch of line - still wearing the round brown hat",2,"Out on the wire in that hat?",1,"Says if his privates have to look at this, they're gonna see him standing in front of it with the hat on"}},
{"s5_camp_payday_042","any",3,"reg=military|day=20,40|mood=funny",{1,"First of the month - payday",2,"Direct deposit into a bank in Radcliff with no lights on",3,"I'm rich somewhere - on paper, in the dark"}},
{"s5_camp_greyhound_043","any",2,"reg=military|day=1,30|mood=sad|world=vehicle",{1,"I had leave approved starting the twelfth, bus ticket to Tampa",2,"Still got the ticket?",1,"In my wallet, folded up with the leave form - both of 'em signed"}},
{"s5_camp_wait_one_044","any",2,"reg=military|day=4,60|mood=funny",{1,"Battalion asked what we need - Sims grabbed the handset",2,"What'd he ask for?",1,"Water, batteries, chow, and somebody up there with a sense of humor",2,"And?",1,"They said wait one, that was Tuesday"}},
{"s5_camp_chaplain_names_045","any",3,"reg=military|day=2,40|mood=sad|world=vehicle",{1,"Chaplain came through on the water truck, held a service in the motor pool",2,"Who went?",1,"Everybody off the wire, even Sikes, and Sikes don't believe in anything but diesel",3,"What did the chaplain say?",1,"Not much - read the names he had, asked us to say out loud the ones he didn't"}},
{"s5_camp_ambulance_alternator_046","any",2,"reg=military|tmp=seasoned,veteran|day=6,90|mood=calm|world=vehicle",{1,"Alternator on the second Humvee is shot",2,"Pull the one off the ambulance",1,"We're allowed to strip the ambulance?",2,"Ambulance doesn't have patients anymore, it's parts now"}},
{"s5_camp_ohio_bunk_047","any",3,"reg=military|day=5,29|hour=0,5|mood=fear",{1,"Ohio's bunk is empty",2,"Latrine?",1,"Checked it, his rifle's here - his boots aren't",3,"Go get the Sergeant, don't holler it - just walk over and get him"}},
{"s5_camp_ohio_sunrise_048","any",2,"reg=military|day=6,29|hour=4,9|mood=warm|world=fence,trees",{1,"Found Ohio at the north fence at dawn, sitting down, facing the woods",2,"He try to go over?",1,"Said he was just looking, said he could tell which way home was from where the sun came up",2,"Sergeant chew him out?",1,"Sergeant sat down next to him a while, then they both walked back to chow"}},
{"s5_camp_car_dealer_ad_049","any",2,"reg=military|day=0,10|mood=sad|world=vehicle",{1,"Last thing on the dayroom TV was that long Emergency Broadcast tone - then a car lot commercial out of Elizabethtown",2,"A car commercial?",1,"Guy in a cowboy hat yelling zero down, somebody forgot to pull the tape"}},
{"s5_camp_nineteen_050","any",1,"reg=military|role=soldier_nco|day=5,90|hour=22,4|mood=grim",{1,"Twenty-six when we came out here - nineteen now",1,"Not asking for more than nineteen by morning, just the nineteen"}},
{"s5_camp_engineer_wire_051","any",3,"reg=military|mood=funny",{1,"Engineers want to know why the infantry keeps walking into their wire",2,"Because they string it right where we walk",3,"We string it where the enemy walks - take the hint"}},
{"s5_camp_sleeves_up_052","any",2,"reg=military|day=4,40|mood=calm",{1,"MPs check everybody's arms in the chow line now, sleeves up to the shoulder",2,"Officers too?",1,"Only officer left this side of the wire is the major, and he eats in his tent",2,"Huh"}},
{"s5_camp_week_three_053","any",3,"reg=military|role=soldier_green|day=0,20|mood=fear",{1,"I was in week three - week three, we hadn't even done the gas chamber",2,"I was week seven, did the gas chamber, didn't help a bit",3,"I was supposed to graduate on the sixteenth, my dad took off work",1,"He come down?",3,"Gate was closed"}},
{"s5_camp_empty_canteen_054","any",2,"reg=military|hour=10,18|mood=funny",{1,"Sergeant makes me drink a canteen and show him it's empty every hour",2,"He wants me to pee in a bottle so he can check the color",1,"That's not true",2,"He's thinking about it, I can see it on his face"}},
{"s5_camp_vine_grove_055","any",3,"reg=military|day=1,30|mood=sad|world=fence,road",{1,"You're Guard, right? From around here?",2,"Vine Grove, twenty minutes from this fence",1,"Your folks?",2,"Outside the line, the good side - they're fine",3,"Then why do you keep watching that road?",2,"Little sister was at a sleepover in Muldraugh that Friday"}},
{"s5_camp_no_glow_056","any",2,"reg=military|hour=20,23|mood=calm",{1,"No chemlights after dark - Sergeant says they see the glow",2,"They can see?",1,"Something brings 'em, I'm not testing which part"}},
{"s5_camp_drink_water_057","any",3,"reg=military|mood=funny",{1,"Doc's answer to everything is drink water",2,"Broke a finger in basic - drink water",3,"Doc, the dead are coming over the wire",1,"Okay, but have you had any water?"}},
{"s5_camp_dry_letters_058","any",2,"reg=military|day=20,120|hour=18,23|mood=sad",{1,"Burn barrel won't catch, somebody's feeding it letters",2,"Whose?",1,"Mine, they were dry - that's about all they had going for them"}},
{"s5_camp_flies_059","any",2,"reg=military|hour=13,16|mood=funny",{1,"Two hundred and twelve",2,"Two hundred and twelve what?",1,"Flies on the chow tent, lost count at the corner and started over",2,"What'd you get the first time?",1,"Two hundred and twelve, it's a real consistent tent"}},
{"s5_camp_side_b_skip_060","any",3,"reg=military|day=5,120|mood=warm",{1,"Somebody's got a Walkman in the second tent - one tape",2,"What is it?",1,"Don't matter, we've all heard it forty times - everybody knows where it skips",3,"Side B skips right before the good part",1,"The skip is the good part now"}},
{"s5_camp_liquid_air_061","any",2,"reg=military|hour=6,10|mood=funny|world=rain",{1,"Seven in the morning and I'm soaked to the knees",2,"That's dew",1,"That's the air - Kentucky air is a liquid you breathe"}},
{"s5_camp_kilo_six_silent_062","any",3,"reg=military|day=3,40|hour=2,6|mood=grim",{1,"Kilo-Six hasn't checked in since 0200",2,"Their set's been bad all week",1,"Their set was fine at midnight, lieutenant Ames was on it himself",3,"Keep calling, every half hour, all night if that's what it takes"}},
{"s5_camp_pot_roast_063","any",1,"reg=military|tmp=seasoned,veteran|hour=12,17|mood=funny",{1,"Helmet's a slow cooker - Vest's a slow cooker, I'm the pot roast",1,"Three more hours on this line and somebody's gonna need a fork"}},
{"s5_camp_oatmeal_gravel_064","any",3,"reg=military|day=1,20|mood=warm",{1,"Package came the day before they shut the gate, from my mamaw in Paducah",2,"What's in it?",1,"Oatmeal cookies - Crumbled in the mail, it's a shoebox of oatmeal gravel",3,"Pass the gravel"}},
{"s5_camp_helmet_band_065","any",2,"reg=military|tmp=veteran,seasoned|day=3,90|mood=grim",{1,"Write your name on your helmet band - big letters",2,"Name tape's right here on my chest",1,"Chest gets dirty, helmet band's easier to read"}},
{"s5_cordon_stationwagon_001","any",3,"reg=military|day=1,10|hour=4,11|mood=sad|world=window",{1,"Blue station wagon this morning - Indiana plates, cat carrier in the back window",2,"We turned it around",1,"I know we turned it around, I was standing right there",3,"Cat hollered the whole time, you could hear it through the glass",2,"Drink your water"}},
{"s5_cordon_roe_card_002","any",2,"reg=military|tmp=seasoned,veteran|day=1,14|mood=angry",{1,"ROE card says verbal warning, show the weapon, then a warning shot - it's printed right here in black and white",2,"Card was printed before Friday",1,"So the card's wrong now?",2,"The card is paper, Specialist - put it back in your pocket"}},
{"s5_cordon_orange_line_003","any",3,"reg=military|day=1,12|mood=calm|world=vehicle",{1,"Who painted that orange stripe out past the barrier?",2,"Engineers, fifty meters out - anybody steps over it, you challenge",3,"Half of it's already wore off under the tires",2,"Then go paint it again",3,"With what, Sergeant? The paint truck went back to post Wednesday"}},
{"s5_cordon_followed_orders_004","any",2,"reg=military|tmp=seasoned,veteran|day=3,60|mood=grim|world=fence",{1,"Pruitt asked me about the fence again, about that night shift",2,"And you said what?",1,"Said we followed orders and nobody got through",2,"That's what happened",1,"Yeah"}},
{"s5_cordon_loudspeaker_mutter_005","any",1,"reg=military|role=soldier,soldier_green|day=1,20|mood=fear",{1,"This area is under federal quarantine - turn your vehicle around, return to your homes",1,"Said it four hundred times today, I say it in my sleep now, Ramirez told me so",1,"Return to your homes, like half of 'em still got a home to go back to"}},
{"s5_cordon_truck_title_006","any",3,"reg=military|day=1,10|mood=sad|world=vehicle",{1,"Old man at the barrier had his truck title out - signed it over right there on the hood",2,"Signed it over to who?",1,"To me, I take the truck, he walks through, that was the deal he wanted",3,"What kind of truck?",1,"Does it matter what kind of truck?",3,"Guess not - sorry"}},
{"s5_cordon_cwire_gloves_007","any",2,"reg=military|tmp=seasoned,veteran|day=1,15|mood=funny",{1,"Three pairs of leather gloves on that concertina and my hands still look like I lost a fight with a bobcat",2,"Engineers strung ten miles of it in two days - go look at their hands",1,"Engineers don't have hands no more, just wire with thumbs"}},
{"s5_cordon_mopp_four_008","any",3,"reg=military|day=0,6|hour=10,18|mood=angry",{1,"Somebody up the chain decided it was a gas, so we stood the line in MOPP Four - in July - in Kentucky",2,"Harris went down in forty minutes, face red as a beet",3,"They pulled the order at noon, nobody said sorry",1,"Army don't say sorry - Army says drink water"}},
{"s5_cordon_yellow_umbrella_009","any",2,"reg=military|day=2,20|mood=sad",{1,"Lady with the yellow umbrella came back, fourth day running",2,"Same question?",1,"Same one, her boy works nights at a hospital up in Louisville - wants to know if we heard anything",2,"Nobody's heard a thing out of Louisville",1,"I told her I'd ask around, she thanked me - she thanked me, man"}},
{"s5_cordon_bridge_tally_010","any",2,"reg=military|day=1,8|hour=4,9|mood=grim|world=cars",{1,"Tallied cars on the bridge approach since dawn, two hundred and eleven",2,"How many got across?",1,"None, that's sort of the point of the tally",2,"Then what's the number for?",1,"Captain wanted a figure for the net, and I needed something to do with my hands"}},
{"s5_cordon_ham_biscuit_011","any",3,"reg=military|day=1,20|mood=funny",{1,"Nobody on this line chats with civilians - you challenge 'em, point 'em, step back",2,"Sergeant, a lady over there just asked if I was hungry",1,"And what did you say?",2,"Said yes, Sergeant",3,"She gave him a ham biscuit wrapped in a napkin",1,"Split it three ways and quit talking"}},
{"s5_cordon_grandma_letter_012","any",2,"reg=military|day=2,40|mood=sad|world=rain",{1,"Boy pushed a letter through the wire yesterday, addressed to his grandma in Elizabethtown, stamp and all",2,"You gonna do something with it?",1,"Mail don't run, it's in my helmet band",2,"Better take it out before it rains, then"}},
{"s5_cordon_wire_singing_013","any",2,"reg=military|hour=21,4|mood=fear",{1,"You hear that? Out past the second strand",2,"Wire's singing, one of them walked into it",1,"How do you know it's one of them?",2,"Because a person would have quit pushing by now"}},
{"s5_cordon_private_biscuit_014","any",3,"reg=military|day=1,30|hour=4,11|mood=warm",{1,"Beagle came under the wire at the culvert this morning - nobody shot it",2,"Nobody was ever told to shoot dogs",3,"Morales gave it half his crackers, it's asleep in the back of the Humvee",1,"It got a name yet?",3,"Private Crackers, he outranks you by lunch"}},
{"s5_cordon_sunburn_015","any",3,"reg=military|day=2,20|mood=angry|world=road",{1,"That family on the Brandenburg road wasn't sick, I looked at 'em",2,"You looked at 'em from sixty meters through a rear sight",1,"The little girl had a sunburn, that's all she had - a sunburn",3,"Both of you knock it off - it's done",1,"That's what I'm saying - it's done"}},
{"s5_cordon_dozer_cab_016","any",2,"reg=military|hour=11,17|mood=funny|world=door,road",{1,"Remember Tate refusing to get out of that dozer?",2,"Only air-conditioned cab we'd found that day",1,"Thought he'd run it dry",2,"Said he was guarding it. Said it very firmly and wouldn't unlock the door"}},
{"s5_cordon_preacher_017","any",2,"reg=military|day=2,20|mood=calm",{1,"Preacher from one of the churches in Muldraugh walked up to the barrier - asked could he pray over us",2,"Sergeant let him?",1,"Let him stand on his side of the paint and pray loud - took his own cover off for it",2,"Sergeant did?",1,"Sergeant did"}},
{"s5_cordon_bicycle_boy_018","any",2,"reg=military|day=1,10|mood=sad",{1,"Boy on a bicycle kept riding up to the line and turning around - up and back, all afternoon",2,"What did he want?",1,"Never said, just kept looking at us like we might change our minds if he did it enough"}},
{"s5_cordon_bluegill_019","any",3,"reg=military|day=1,8|mood=calm",{1,"Guy showed me a Jefferson County license, said he don't even live here, he only came down for the fishing",2,"Don't matter where he lives",3,"He had a whole cooler of bluegill on ice, tried to give me the bluegill",1,"Everybody out there is trying to hand us something"}},
{"s5_cordon_trooper_cruiser_020","any",2,"reg=military|day=0,5|mood=angry|world=vehicle,road",{1,"State trooper at the Ekron junction told our LT this is a state road and he don't take orders from the Guard",2,"And?",1,"LT got on the net, twenty minutes later that cruiser was on the wrong side of the wire",2,"Still sitting there, I bet",1,"Lights still going, battery's gonna die before his pride does"}},
{"s5_cordon_long_pole_021","any",2,"reg=military|hour=5,9|mood=grim|world=road",{1,"Six hung up on the concertina between post two and post three this morning",2,"Moving?",1,"Four of them moving",2,"Get the pole team, nobody fires until the civilians are off that road"}},
{"s5_cordon_frogs_022","any",2,"reg=military|hour=22,2|mood=funny",{1,"Relief's here - anything to report?",2,"Frogs, about two thousand frogs, and the dead, but mainly the frogs",1,"Frogs are not a report",2,"Sit out there six hours in that ditch and tell me frogs aren't a report"}},
{"s5_cordon_including_our_own_023","any",3,"reg=military|day=1,20|hour=0,5|mood=grim",{1,"Net traffic at {time} changed the orders again, nobody in or out, including our own",2,"Including our own? What's that supposed to mean?",3,"It means you walk out past the line, you don't walk back in",2,"Even us?",1,"Us most of all"}},
{"s5_cordon_twelve_names_024","any",2,"reg=military|day=3,40|mood=sad",{1,"Woman handed me a list of names across the barrier - folks she's looking for, twelve names in pencil",2,"What'd you do with it?",1,"Read 'em, every one, out loud, so she'd know I did"}},
{"s5_cordon_duck_bullhorn_025","any",2,"reg=military|day=2,25|mood=funny",{1,"Bullhorn's dying, I sound like a duck asking folks to kindly return home",2,"People listen better to a duck",1,"They do not, a lady laughed right in my face",2,"First laugh on this line since Friday - keep the duck"}},
{"s5_cordon_towel_026","any",3,"reg=military|day=1,10|mood=fear|world=vehicle",{1,"Red pickup came at the barrier doing fifty, maybe sixty",2,"Jersey barriers held",3,"Driver didn't",1,"He was bit, had his forearm wrapped in a beach towel - that's why he tried it",2,"You don't know that",1,"I found the towel"}},
{"s5_cordon_post_four_027","any",1,"reg=military|tmp=seasoned|day=5,60|mood=sad",{1,"Keep telling myself I was on post four, post four was quiet that whole night",1,"I wasn't on post four",1,"Bootlace keeps coming undone, third time today - can't get the knot to hold"}},
{"s5_cordon_johnboats_028","any",3,"reg=military|day=2,20|hour=19,23|mood=grim|world=cars",{1,"Boat on the Ohio says there's johnboats trying to cross every night now",2,"We got a boat out there?",1,"Somebody with a searchlight is out there, says Coast Guard when they come up on the net",3,"What happens to the johnboats?",1,"They get told to turn around, same as the cars",3,"And if they don't?",1,"Same as the cars"}},
{"s5_cordon_halt_practice_029","any",2,"reg=military|role=soldier_nco,soldier_green|day=0,20|mood=fear",{1,"Private, somebody walks up to that line - what do you say?",2,"Halt, Sergeant, then, um, this area is closed",1,"Louder, your voice is shaking worse than your hands",2,"HALT! This area is closed!",1,"Better, now say it like you mean it and I'll quit asking"}},
{"s5_cordon_moon_pies_030","any",3,"reg=military|day=1,20|mood=warm",{1,"Somebody once left Moon Pies by the barrier. Note said, for the boys, God bless",2,"You didn't worry about what was in them?",3,"I worried. Hated that my first thought about a kindness was being scared of it",2,"I'd have wanted a banana one. Wouldn't have wanted to be the first to say so"}},
{"s5_cordon_museum_bus_031","any",2,"reg=military|day=1,10|mood=calm|world=vehicle",{1,"Indiana, Ohio, Tennessee, two from Illinois, folks drove a long way to get stuck here",2,"There was a tour bus at the Patton Museum when it started - Retirees from Michigan",1,"They get turned back too?",2,"Bus is parked on the shoulder at Muldraugh, they're living in it - one of them keeps bringing us crossword puzzles"}},
{"s5_cordon_police_call_032","any",2,"reg=military|day=3,30|hour=2,6|mood=grim|world=fence",{1,"Police call on the fence line - Sergeant wants every piece of brass picked up",2,"What for? Who's counting brass now?",1,"Didn't say, wants it gone before daylight",2,"Before the families come back to look",1,"Just pick it up"}},
{"s5_cordon_payphone_033","any",3,"reg=military|day=1,6|hour=4,11|mood=sad",{1,"Payphone at the gas station on 31W still had a dial tone yesterday - civilians lined up forty deep",2,"And today?",3,"Cut this morning, signal guys did it",1,"Woman at the front of the line had her quarter in the slot when it went"}},
{"s5_cordon_water_tower_034","any",2,"reg=military|tmp=veteran,seasoned|mood=calm",{1,"Overwatch on the water tower has eyes a mile down the pike - anybody walks in, we know in five minutes",2,"And anything walking in?",1,"Same five minutes, then they take a good while longer to actually get here",2,"Slow suits me fine"}},
{"s5_cordon_throw_two_035","any",3,"reg=military|day=3,15|mood=warm|world=building",{1,"Civilians at the barrier are asking for food now, not to get through - just food",2,"We got MREs stacked to the ceiling in that conex",3,"And orders not to pass anything over the wire - contact risk",2,"Contact risk, from a sealed brown bag",1,"I threw one over - nobody saw",3,"I saw",1,"And?",3,"Throw two next time"}},
{"s5_cordon_password_mutter_036","any",1,"reg=military|role=soldier_green|day=0,29|hour=21,5|mood=fear",{1,"Challenge, then password, challenge is lantern - password is cabin",1,"No, no, lantern, then harbor - cabin was yesterday",1,"Please don't anybody walk up on me tonight, I'll get it wrong"}},
{"s5_cordon_harp_brother_037","any",2,"reg=military|day=2,25|mood=sad",{1,"Deputy on the far side of the wire asked if I knew a Sergeant Wendell Harp - said that's his brother",2,"Harp from Alpha?",1,"Yeah, I didn't have it in me",2,"So what'd you say to him?",1,"Said Harp was on another sector, it's near enough true"}},
{"s5_cordon_county_fair_heat_038","any",3,"reg=military|hour=12,17|mood=funny",{1,"Ninety-seven degrees and the dead still come up to the wire like it's opening night at the county fair",2,"They don't sweat - Unfair advantage",3,"They stink, though - Stink's just sweat that gave up",1,"Thank you, Doctor - real scientific"}},
{"s5_cordon_tank_ditch_039","any",2,"reg=military|day=2,20|mood=calm|world=road",{1,"Engineers used to talk about cutting a tank ditch across a road",2,"Tanks ain't what's coming",1,"No. And I wouldn't promise a ditch would stop them either",2,"Go tell the engineers, they'll want that in writing"}},
{"s5_cordon_camcorder_040","any",2,"reg=military|day=1,8|mood=angry",{1,"Fella with a camcorder was taping us from the Dairy Queen lot",2,"MPs grab it?",1,"Took the tape, gave him back the camera - he asked for a receipt",2,"He get one?",1,"Sergeant wrote it on the flap of an MRE box - one tape, property of the Army"}},
{"s5_cordon_storm_river_041","any",3,"reg=military|hour=14,20|mood=calm|world=water,road",{1,"Here it comes - look at that sky over the river",2,"Good, maybe it'll cool the asphalt",3,"And wash the paint line right off",1,"Get your poncho on, will you? Christ, you're making it sound worse"}},
{"s5_cordon_car_seat_042","any",2,"reg=military|day=2,20|mood=sad|world=vehicle",{1,"She walked right up to the line with a car seat - held it up high so we could see",2,"Was there a baby in it?",1,"Never got close enough to look - Sergeant said step back and she stepped back",2,"Okay",1,"She left it, the car seat's still out there sitting on the orange line"}},
{"s5_cordon_goldfish_043","any",3,"reg=military|hour=18,22|mood=warm|world=cars",{1,"Remember volunteering for the post by the rail crossing?",2,"People kept finding movement under the boxcars",3,"That's why I offered",1,"Why you?",3,"The other man had two kids. I had a goldfish and a roommate I hoped was feeding it"}},
{"s5_cordon_chinooks_044","any",2,"reg=military|day=1,10|mood=fear",{1,"Heard they're airlifting the civilians out of Rosewood - Chinooks up from Campbell",2,"Who told you?",1,"Guy in the chow line",2,"Guy in the chow line also said we rotate home Sunday",1,"Well, I liked that one better"}},
{"s5_cordon_marlboro_carton_045","any",2,"reg=military|day=3,30|mood=funny",{1,"Civilian offered me a whole carton of Marlboros for one look at our map",2,"Did you show him?",1,"I don't smoke",2,"I didn't ask about that!",1,"And that's all I'm saying about it"}},
{"s5_cordon_tree_line_046","any",2,"reg=military|tmp=veteran,seasoned|day=3,40|mood=grim|world=trees",{1,"You keep staring at that tree line like it owes you money",2,"Same tree line they came out of that night",1,"Trees didn't do a thing - watch your sector"}},
{"s5_cordon_nco_list_047","any",1,"reg=military|role=soldier_nco|day=2,60|mood=grim",{1,"I remember counting posts, men, radios. Waiting for relief at 0600",1,"Water runs and ammo counts. Every change, another list",1,"Wrote it all down so there'd be no room left to think"}},
{"s5_cordon_saddled_horse_048","any",3,"reg=military|day=2,20|mood=sad|world=fence",{1,"Somebody's horse is walking the fence on the Fallas Lake side - saddle and all",2,"Rider?",1,"Just the horse, keeps coming back to the gate right about feeding time",3,"I can't stand listening to it, somebody go catch it",2,"Catch it and put it where?"}},
{"s5_cordon_news_van_049","any",2,"reg=military|day=0,4|mood=angry|world=vehicle",{1,"TV van out of Louisville tried to come in on the Dixie Highway - MPs turned it around",2,"They get any pictures?",1,"Got a nice picture of my back, I made sure",2,"Your mama could've seen you on the six o'clock news",1,"My mama would've seen what was behind me"}},
{"s5_cordon_deel_sick_050","any",3,"reg=military|day=3,25|mood=calm",{1,"Private Deel's been sick behind the conex since relief",2,"First time he saw one up close in the wire",3,"I'm fine, I'm okay now, Sergeant, it was the chili mac",1,"It wasn't the chili mac, rinse out, get your helmet on, and come stand next to me"}},
{"s5_cordon_expect_delays_051","any",3,"reg=military|day=2,30|mood=funny|world=road",{1,"Sign behind our barrier still says Road Work Ahead, Expect Delays",2,"Well, they weren't lying",3,"Somebody at the highway department deserves a raise for that sign"}},
{"s5_cordon_elbow_wave_052","any",2,"reg=military|day=1,15|mood=warm|world=building",{1,"Two kids on a porch past the wire wave at every Humvee that goes by - every single one",2,"You wave back?",1,"Not allowed to, so I wave with my elbow"}},
{"s5_cordon_still_talking_053","any",3,"reg=military|day=1,20|hour=18,23|mood=fear",{1,"Listen up, tonight they'll come to the wire and some of them will still be talking - you don't answer",2,"Still talking, Sergeant? The sick ones talk?",1,"The ones who aren't sick yet, you don't answer them either",3,"Then who do we answer?",1,"Me"}},
{"s5_cordon_light_tower_054","any",2,"reg=military|hour=20,23|mood=funny|world=generator",{1,"Light towers are up, generator drinks a can of diesel every six hours",2,"And the bugs drink a pint of me every six minutes",1,"Then step out of the light, genius"}},
{"s5_cordon_curb_man_055","any",2,"reg=military|day=1,20|mood=sad|world=vehicle",{1,"Man at the barrier said his wife's gone and his girl's gone - then asked real polite could he just go on through",2,"And we said no",1,"He said alright then, thank you, and went and sat in his truck - truck hasn't moved"}},
{"s5_cordon_short_thirty_056","any",2,"reg=military|tmp=veteran,seasoned|day=3,60|mood=grim",{1,"Ammo count at post two is short thirty rounds from yesterday",2,"Night shift fired on the wire",1,"Log says no shots fired",2,"Then the log's short thirty rounds, Sergeant"}},
{"s5_cordon_knock_knock_057","any",3,"reg=military|day=1,30|mood=funny|world=door",{1,"Knock knock",2,"Not now",1,"Knock knock",3,"Fine, who's there?",1,"Quarantine",3,"Quarantine who?",1,"Doesn't matter who, you're not coming in",2,"Ain't a joke, just the job with a door in the way"}},
{"s5_cordon_humvee_hood_058","any",2,"reg=military|hour=11,17|mood=funny",{1,"Put your hand flat on that Humvee hood",2,"Why in the world would I do that?",1,"Because I just did, and I don't want to be the only idiot"}},
{"s5_cordon_gas_sign_059","any",3,"reg=military|day=2,40|mood=funny",{1,"Sign at the station still says regular, a dollar and nine",2,"Pumps have been dry since Monday",3,"A dollar nine for nothing, best deal in Kentucky",1,"I'd still pay it, I'd pay it just to hear the pump click"}},
{"s5_cordon_no_cars_060","any",3,"reg=military|day=5,40|mood=grim|world=cars",{1,"No cars today, first whole day with no cars",2,"Good",3,"Is it?",1,"Means there's nobody out there with gas left, or nobody left to drive it",2,"I said good - let me keep it"}},
{"s6_c01_carrier_hiss_001","any",2,"reg=elite|tmp=veteran|hour=1,4|mood=grim|world=window",{1,"Window opened at 0200, closed at 0215",2,"And?",1,"And I listened to fifteen minutes of carrier hiss"}},
{"s6_c01_pace_plan_002","any",3,"reg=elite|tmp=veteran|day=5,999|mood=grim",{1,"Primary's dead - Alternate's dead - Contingency's dead",2,"Emergency is the payphone at the gas station in Muldraugh",3,"Phones have been dead since the weekend",1,"Then we write a new plan on the back of the old one"}},
{"s6_c01_second_try_003","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Voice on our freq, knows our callsign",2,"Authenticate him",1,"Did, he got it wrong, then got it right on the second try",2,"Nobody gets a second try - change freqs"}},
{"s6_c01_three_words_004","any",2,"reg=elite|tmp=veteran|day=8,999|mood=sad",{1,"Pad's on its last sheet",2,"Then keep the message short",1,"Shortest thing I have to say is three words",2,"Which three?",1,"Come get us"}},
{"s6_c01_bird_due_005","any",2,"reg=elite|tmp=veteran|day=3,999|mood=funny",{1,"Bird was due at the LZ at 0330",2,"What time is it?",1,"Tuesday"}},
{"s6_c01_panel_ballfield_006","any",2,"reg=elite|tmp=veteran|day=9,999|mood=grim",{1,"Panel's still laid out on the high school ball field",2,"Nine days - pick it up",1,"Leave it, something with rotors might come over",2,"Something with rotors did come over, it kept going"}},
{"s6_c01_listening_schedule_007","any",2,"reg=elite|tmp=veteran|day=6,999|mood=calm|world=window",{1,"Last BA-5590, fourteen hours of listening if we're careful",2,"Windows only, we listen at the windows",1,"There haven't been windows for four days, I'm listening to nothing on a schedule",2,"Keep the schedule"}},
{"s6_c01_grid_twice_008","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Picked up a Guard battalion net near West Point",2,"Anything useful?",1,"A captain asking three times for a grid he'd already been given",2,"So, a normal Tuesday for the Guard"}},
{"s6_c01_too_well_009","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Checkpoint on 31W doesn't know we exist",2,"Nobody does, that was the idea",1,"Idea's working a little too well"}},
{"s6_c01_bluegrass_010","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"What's the codeword for mission complete?",2,"Bluegrass",1,"And for mission cancelled?",2,"Nobody gave us one"}},
{"s6_c01_nebraska_ham_011","any",2,"reg=elite|tmp=veteran|hour=21,4|mood=funny",{1,"HF skips better after dark, had Nebraska for a minute",2,"Army?",1,"A ham in his basement, wanted a signal report",2,"You give him one?",1,"Five by nine, didn't mention anything else"}},
{"s6_c01_acknowledged_012","any",2,"reg=elite|tmp=veteran|day=4,999|mood=funny",{1,"SATCOM's got a lock",2,"Send it",1,"Sent, they came back",2,"That's a first - what'd they say?",1,"Acknowledged"}},
{"s6_c01_where_they_were_013","any",2,"reg=elite|tmp=veteran|day=3,999|mood=grim",{1,"{callsign} missed three checks",2,"They were in Louisville",1,"I know where they were"}},
{"s6_c01_reading_plates_014","any",2,"reg=elite|tmp=veteran|day=1,6|mood=grim|world=cars",{1,"Sheriff's channels went quiet around noon",2,"All of them?",1,"Last one was a deputy reading plates off the cars on a bridge - just reading plates, for an hour"}},
{"s6_c01_answering_service_015","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=funny",{1,"Got the client on the briefcase phone",2,"Somebody picked up?",1,"Answering service - nice lady, took a message",2,"They'll call back",1,"She said that too"}},
{"s6_c01_hazard_clause_016","any",2,"reg=elite|role=mercenary|tmp=veteran|day=10,999|mood=grim",{1,"Contract says hazard pay starts after day ten",2,"Who's cutting the check?",1,"I'm keeping count anyway, a man needs something to keep count of"}},
{"s6_c01_porch_log_017","any",2,"reg=elite|tmp=veteran|mood=calm|world=window,building",{1,"We missed the 1800 window, we were under a porch in Rosewood",2,"Log it as missed",1,"Log the porch?",2,"Log 'missed.' Nobody up there needs the porch"}},
{"s6_c01_on_the_card_018","any",2,"reg=elite|role=elite_delta|tmp=veteran|day=4,999|mood=funny",{1,"Status",2,"Ammo green - water amber - radio black",1,"Radio's been black since Sunday, quit reporting it",2,"It's on the card, I report the card"}},
{"s6_c01_request_unchanged_019","any",1,"reg=elite|tmp=veteran|day=5,999|hour=5,8|mood=sad",{1,"{callsign}, this is Six - Sitrep follows",1,"Four pax - location unchanged - request unchanged",1,"Six, out, same as yesterday"}},
{"s6_c01_point_two_seconds_020","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Burst went out - Point two seconds",2,"Somebody would've had to blink at exactly the right time",1,"Somebody blinked, has to be somebody"}},
{"s6_c01_your_discretion_021","any",2,"reg=elite|tmp=veteran|day=2,999|mood=grim|world=vehicle",{1,"Last traffic moved the pickup to Godman Field",2,"Inside Knox? Through the cordon?",1,"Through the cordon, through Muldraugh, through whatever's on 31W",2,"They say how?",1,"They said 'at your discretion'"}},
{"s6_c01_tower_lights_022","any",2,"reg=elite|tmp=veteran|hour=20,5|mood=calm|world=vehicle,generator",{1,"Lights on in the tower at Godman",2,"Generator on a timer",1,"Timers don't switch off when a truck drives past"}},
{"s6_c01_his_address_023","any",2,"reg=elite|tmp=veteran|mood=grim|world=road",{1,"Some fool on channel nineteen is reading out his address - street and house number",2,"Asking for help?",1,"Asking for company, he'll get some"}},
}
